import 'package:test/test.dart';
import 'package:viem_dart_tooling/src/locked_package.dart';

const _lock = '''
# Generated by pub
packages:
  async:
    dependency: transitive
    description:
      name: async
      sha256: "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
      url: "https://pub.dev"
    source: hosted
    version: "2.13.1"
  viem_dart:
    dependency: "direct main"
    description:
      path: "packages/viem_dart"
      relative: true
    source: path
    version: "0.0.1"
  from_git:
    dependency: "direct main"
    description:
      url: "https://example.org/x.git"
    source: git
    version: "1.0.0"
  zeta:
    dependency: "direct main"
    description:
      name: zeta
      sha256: "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"
      url: "https://pub.dev"
    source: hosted
    version: "1.0.0-dev.3"
sdks:
  dart: ">=3.12.2 <4.0.0"
''';

void main() {
  test('parseHostedLockEntries keeps hosted packages only', () {
    final entries = parseHostedLockEntries(_lock);
    expect(entries.keys, ['async', 'zeta']);
    expect(entries['async']!.version, '2.13.1');
    expect(entries['async']!.sha256, 'a' * 64);
    expect(entries['zeta']!.version, '1.0.0-dev.3');
  });

  test('parseHostedLockEntries on an empty lockfile finds nothing', () {
    expect(parseHostedLockEntries('packages:\nsdks:\n'), isEmpty);
  });

  test(
    'parsePackageConfigDirectories resolves absolute and relative roots',
    () {
      final dirs = parsePackageConfigDirectories(
        '{"packages":[{"name":"a","rootUri":"file:///cache/a-1.0.0"},'
        '{"name":"b","rootUri":"../packages/b"}]}',
        Uri.parse('file:///ws/.dart_tool/package_config.json'),
      );
      expect(dirs['a']!.uri.path, '/cache/a-1.0.0/');
      expect(dirs['b']!.uri.path, '/ws/packages/b/');
    },
  );

  test('directDependencies reads dependencies but not dev_dependencies', () {
    const pubspec = '''
name: x
dependencies:
  http: ^1.6.0
  pointycastle: ^4.0.0

dev_dependencies:
  test: ^1.31.2
''';
    expect(directDependencies(pubspec), {'http', 'pointycastle'});
    expect(directDependencies('name: x\n'), isEmpty);
  });

  test(
    'runtimeClosureFrom follows dependencies and leaves dev packages out',
    () {
      const deps = '''
{"root":"app","packages":[
 {"name":"app","dependencies":["http","test"]},
 {"name":"http","dependencies":["meta"]},
 {"name":"meta","dependencies":[]},
 {"name":"test","dependencies":["matcher"]},
 {"name":"matcher","dependencies":[]}]}''';
      expect(runtimeClosureFrom(deps, {'http'}), {'http', 'meta'});
    },
  );
}
